export const scripts: string[] = ["\n    const planData = {\n      comprehensive: {\n        badge: \"All-In-One Flagship\",\n        price: \"\u20b9735\",\n        unit: \"/month*\",\n        headline: \"Star Comprehensive Insurance\",\n        summary: \"Complete family shielding with unlimited automatic restoration, zero room rent capping, and built-in maternity & newborn care.\",\n        features: [\n          \"Single Standard A/C Room without sub-limits or pro-rata deductions\",\n          \"Maternity cover up to \u20b91,00,000 + Newborn vaccine cover up to 1 year\",\n          \"100% Unlimited restoration up to sum insured for subsequent hospitalizations\"\n        ]\n      },\n      senior: {\n        badge: \"Parents 60-75 Yrs\",\n        price: \"\u20b91,120\",\n        unit: \"/month*\",\n        headline: \"Senior Citizens Red Carpet\",\n        summary: \"Specially formulated for elderly parents without mandatory pre-acceptance health checks or stress treadmill tests.\",\n        features: [\n          \"Direct entry up to 75 years without pre-policy medical screenings\",\n          \"Tailored coverage for Diabetes & Hypertension under specific terms\",\n          \"Dedicated outpatient specialist consults & lifetime renewal guarantee\"\n        ]\n      },\n      young: {\n        badge: \"Ages 18 to 40\",\n        price: \"\u20b9480\",\n        unit: \"/month*\",\n        headline: \"Star Young Star Insurance\",\n        summary: \"Engineered for young professionals & newlyweds desiring zero co-pay, health track discounts, and modern day care covers.\",\n        features: [\n          \"Zero co-payment options with high sum insured multiples\",\n          \"Up to 10% wellness premium rebate for maintaining daily active steps\",\n          \"Modern advanced laparoscopic, robotic & laser procedures covered\"\n        ]\n      },\n      floater: {\n        badge: \"Most Trusted Floater\",\n        price: \"\u20b9640\",\n        unit: \"/month*\",\n        headline: \"Star Family Health Optima\",\n        summary: \"Reliable household floater protection with cumulative bonus growth up to 100% and organ donor surgical cost shields.\",\n        features: [\n          \"Cumulative bonus multiplier: Up to 100% increase in sum insured\",\n          \"Emergency Air Ambulance coverage up to 10% of sum insured\",\n          \"Complete organ donor hospitalization expenses included\"\n        ]\n      }\n    };\n\n    function selectPlan(planKey) {\n      const data = planData[planKey];\n      if (!data) return;\n\n      // Update Tabs Style\n      const tabs = document.querySelectorAll('.plan-tab-btn');\n      tabs.forEach(tab => {\n        if (tab.getAttribute('data-tab') === planKey) {\n          tab.className = 'plan-tab-btn py-2 px-space-xs rounded font-label-prominent text-[13px] text-center transition-all bg-primary text-on-primary font-bold shadow-sm';\n        } else {\n          tab.className = 'plan-tab-btn py-2 px-space-xs rounded font-label-prominent text-[13px] text-center transition-all text-on-surface-variant hover:text-primary font-medium';\n        }\n      });\n\n      // Update Plan Details\n      document.getElementById('plan-badge').textContent = data.badge;\n      document.getElementById('plan-price').innerHTML = `${data.price}<span class=\"font-body-sm text-body-sm font-normal text-on-surface-variant\">${data.unit}</span>`;\n      document.getElementById('plan-headline').textContent = data.headline;\n      document.getElementById('plan-summary').textContent = data.summary;\n\n      const featContainer = document.getElementById('plan-features');\n      featContainer.innerHTML = '';\n      data.features.forEach(feat => {\n        const li = document.createElement('li');\n        li.className = 'flex items-center gap-2';\n        li.innerHTML = `<span class=\"material-symbols-outlined text-secondary text-[16px]\">check_circle</span><span>${feat}</span>`;\n        featContainer.appendChild(li);\n      });\n    }\n\n    function toggleFaq(index) {\n      const ans = document.getElementById(`faq-ans-${index}`);\n      const icon = document.getElementById(`faq-icon-${index}`);\n      if (!ans || !icon) return;\n\n      const isHidden = ans.classList.contains('hidden');\n      if (isHidden) {\n        ans.classList.remove('hidden');\n        icon.textContent = 'expand_less';\n        icon.parentElement.parentElement.classList.add('bg-surface-container-low');\n      } else {\n        ans.classList.add('hidden');\n        icon.textContent = 'expand_more';\n        icon.parentElement.parentElement.classList.remove('bg-surface-container-low');\n      }\n    }\n\n    function handleQuoteSubmit(e) {\n      e.preventDefault();\n      const name = document.getElementById('lead-name').value;\n      const phone = document.getElementById('lead-phone').value;\n      const age = document.getElementById('lead-age').value;\n      const coverage = document.getElementById('lead-coverage').value;\n      \n      const text = encodeURIComponent(`Star Health Quote Inquiry from Deeksha Website:\\nName: ${name}\\nPhone: ${phone}\\nEldest Age: ${age}\\nRequested Coverage: ${coverage}`);\n      window.open(`https://wa.me/916374423164?text=${text}`, '_blank');\n    }\n  "];
